def _pick_tile(B, C, Ho, Wo, cores):
    cands = [
        (bh, bw)
        for bh, bw in _TILES
        if BH_OK(B, C, Ho, Wo, bh, bw)
    ]
    best = None
    best_score = None
    for bh, bw in cands:
        tiles = B * C * triton.cdiv(Ho, bh) * triton.cdiv(Wo, bw)
        util = min(1.0, float(cores) / tiles)
        area = bh * bw
        # Prefer more utilized grid (>= cores) and then larger tiles.
        score = (util, area)
        if best_score is None or score > best_score:
            best_score = score
            best = (bh, bw)
    return best


def BH_OK(B, C, Ho, Wo, bh, bw):
    return True


